import{_ as o,l as s,o as a,c as i,v as r,p as l,x as t,d as n,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Spectre v1 / v2","description":"","frontmatter":{"title":"Spectre v1 / v2","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spectre-variants.md","filePath":"cs/spectre-variants.md","lastUpdated":1789023840000}'),h={name:"cs/spectre-variants.md"};function E(v,e,B,A,_,f){const c=s("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="spectre-v1-v2" tabindex="-1">Spectre v1 / v2 <a class="header-anchor" href="#spectre-v1-v2" aria-label="Permalink to &quot;Spectre v1 / v2&quot;">​</a></h1><div class="epigraph"><p>分支预测让错误路径上的 load 仍然发生；架构状态回滚之后，缓存占用还在。v1 是条件方向，v2 是间接目标被训练到错误处。</p><footer>—— 据 Kocher et al., Spectre Attacks, IEEE S&amp;P 2019 整理</footer></div><p><a href="/cs/mttf-redundancy">上一课</a> 管随机翻转。<a href="/cs/speculation-recovery">推测恢复</a> 已写明：cache 填充不随 ROB 冲刷回滚。<a href="/cs/transient-exec">瞬态执行对照</a> 在安全主干点过名。本课在微结构进阶里把 <strong>Spectre v1（边界检查绕过）与 v2（分支目标注入）接到 gshare/BTB</strong>，只讲机制与缓解，不给探测程序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/gshare-predictor">gshare</a> 与 <a href="/cs/indirect-branch-predict">间接预测</a> 故意在核对前取指执行。错误路径上的 load 可以用推测值当索引去碰 cache。<a href="/cs/speculation-recovery">恢复</a> 丢掉寄存器写，不丢 L1 占用。缺口不是再加 ECC，而是<strong>承认预测器 + cache 是安全边界，而不只是 CPI 旋钮。</strong></p><p><span class="marginnote">v1：条件误预测让越界下标在检查失败前执行。v2：间接 BTB/ITT 被训练到错误目标。缓解包括序列化、间接目标隔离、编译器栅栏，皆有性能税。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：敏感下标不按推测值索引；编译器在检查后插入硬序列化（实现相关）。系统：间接分支隔离（每进程 BTB 上下文）、限制跨特权训练。微码可改预测器行为。本课不描述如何训练预测器去越权读。</p>',8)),(a(),l(d,null,{default:t(()=>[p(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRED%5B%22%E6%96%B9%E5%90%91%E6%88%96%E7%9B%AE%E6%A0%87%E9%A2%84%E6%B5%8B%22%5D%20--%3E%20SPEC%5B%22%E9%94%99%E8%AF%AF%E8%B7%AF%E5%BE%84%20load%22%5D%0A%20%20SPEC%20--%3E%20ARCH%5B%22ROB%20%E5%86%B2%E5%88%B7%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20SPEC%20--%3E%20CACHE%5B%22cache%20%E5%8D%A0%E7%94%A8%E7%95%99%E4%B8%8B%22%5D%0A%20%20CACHE%20--%3E%20MIT%5B%22%E9%9A%94%E7%A6%BB%20%2F%20%E5%BA%8F%E5%88%97%E5%8C%96%20%2F%20%E9%99%90%E5%88%B6%E8%AE%AD%E7%BB%83%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 <a href="/cs/fence-cost">fence 代价</a> 直接冲突：关掉推测就回到深管线的误预测损失。<a href="/cs/loop-predictor">循环器</a> 与 TAGE 越准，攻击面的「可用错误路径」形态在变，但不会消失。SMT 共核共享预测器与 cache，信任域应视为合并。</p><p>retpoline 一类把间接跳转改成不会走被污染 BTB 的序列，是 v2 的软件补丁，前端带宽与 <a href="/cs/uop-cache">uop cache</a> 命中都会变差。硬件间接隔离之后可以关掉部分补丁。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列变体编号大全，不给测量代码。Meltdown 下一课是故障抑制而不是分支预测。KPTI 是 OS 对故障路径的页表药方。Rowhammer 是 DRAM 物理层，再下一课。</p><p>后课默认：v1/v2 的根是预测 + 不可回滚的 cache。故障路径上的特权检查被乱序绕过，是 Meltdown。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Spectre v1/v2 把分支预测器接到缓存足迹。</li><li>缓解是限制推测与隔离预测器状态，对 CPI 不免费。</li><li>故障抑制路径是下一课 Meltdown。</li><li>出处：Kocher et al., <em>IEEE S&amp;P</em>, 2019。</li></ul>',8))])}const T=o(h,[["render",E]]);export{u as __pageData,T as default};
